create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','hr','employee');
create type public.leave_status as enum ('pending','approved','rejected','cancelled');
create type public.sample_status as enum ('submitted','received_back','lost','used');
create type public.order_status as enum ('received','assigned','in_progress','completed','on_hold','cancelled');
create table public.companies (id uuid primary key default gen_random_uuid(), name text not null, legal_name text, email text, phone text, address text, gstin text, bank_details jsonb not null default '{}'::jsonb, upi_id text, qr_storage_path text, created_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, company_id uuid not null references public.companies(id), full_name text not null, designation text, mobile text, preferred_language text not null default 'en', role public.app_role not null default 'employee', active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.expense_categories (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, name text not null, created_by uuid references auth.users(id), created_at timestamptz not null default now(), unique(company_id,name));
create table public.expenses (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), expense_date date not null, category_id uuid references public.expense_categories(id), category_name text, mode text, start_location text, end_location text, amount numeric(12,2) not null check(amount >= 0), receipt_number text, receipt_path text, remarks text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.expense_revisions (id uuid primary key default gen_random_uuid(), expense_id uuid not null references public.expenses(id) on delete cascade, changed_by uuid not null references auth.users(id), old_values jsonb not null, new_values jsonb not null, changed_at timestamptz not null default now());
create table public.attendance_shifts (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), shift_date date not null, punched_in_at timestamptz not null, punched_out_at timestamptz, created_at timestamptz not null default now(), check(punched_out_at is null or punched_out_at >= punched_in_at));
create table public.attendance_locations (id uuid primary key default gen_random_uuid(), shift_id uuid not null references public.attendance_shifts(id) on delete cascade, captured_at timestamptz not null default now(), latitude double precision not null, longitude double precision not null, accuracy_m integer, address text, consent_recorded boolean not null default false);
create table public.leave_balances (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), leave_year integer not null, leave_type text not null, entitled numeric(6,2) not null default 0, used numeric(6,2) not null default 0, unique(employee_id,leave_year,leave_type));
create table public.leave_requests (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), leave_type text not null, start_date date not null, end_date date not null, days numeric(6,2) not null check(days > 0), reason text, status public.leave_status not null default 'pending', reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, created_at timestamptz not null default now(), check(end_date >= start_date));
create table public.employee_assets (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), asset_type text not null, asset_name text not null, serial_number text, issued_on date, returned_on date, condition_notes text, created_at timestamptz not null default now());
create table public.salary_records (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, employee_id uuid not null references public.profiles(id), salary_month date not null, gross numeric(12,2) not null default 0, deductions numeric(12,2) not null default 0, net numeric(12,2) not null default 0, payment_status text not null default 'draft', private_notes text, created_at timestamptz not null default now(), unique(employee_id,salary_month));
create table public.client_samples (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, client_name text not null, pmt_name text, sample_name text not null, quantity integer not null default 1 check(quantity > 0), brand_name text, photo_path text, status public.sample_status not null default 'submitted', remarks text, created_by uuid references public.profiles(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.orders (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, client_name text not null, po_number text, order_date date not null, product_name text not null, product_code text, quantity integer not null check(quantity > 0), order_value numeric(14,2), brand_name text, status public.order_status not null default 'received', assigned_to uuid references public.profiles(id), created_by uuid references public.profiles(id), remarks text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.audit_events (id uuid primary key default gen_random_uuid(), company_id uuid not null references public.companies(id) on delete cascade, actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, details jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create or replace function public.current_company_id() returns uuid language sql stable security definer set search_path=public as $$ select company_id from public.profiles where id=auth.uid() and active=true $$;
create or replace function public.current_role() returns public.app_role language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() and active=true $$;
create or replace function public.can_manage_company() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.current_role() in ('admin','hr'),false) $$;
alter table public.companies enable row level security;
alter table public.profiles enable row level security;
alter table public.expense_categories enable row level security;
alter table public.expenses enable row level security;
alter table public.expense_revisions enable row level security;
alter table public.attendance_shifts enable row level security;
alter table public.attendance_locations enable row level security;
alter table public.leave_balances enable row level security;
alter table public.leave_requests enable row level security;
alter table public.employee_assets enable row level security;
alter table public.salary_records enable row level security;
alter table public.client_samples enable row level security;
alter table public.orders enable row level security;
alter table public.audit_events enable row level security;
create policy company_read on public.companies for select using (id=public.current_company_id());
create policy profiles_read on public.profiles for select using (company_id=public.current_company_id() and (id=auth.uid() or public.can_manage_company()));
create policy profiles_manage on public.profiles for update using (company_id=public.current_company_id() and public.current_role()='admin') with check(company_id=public.current_company_id());
create policy categories_read on public.expense_categories for select using(company_id=public.current_company_id());
create policy categories_manage on public.expense_categories for all using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id() and public.can_manage_company());
create policy expenses_read on public.expenses for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company()));
create policy expenses_insert on public.expenses for insert with check(company_id=public.current_company_id() and employee_id=auth.uid());
create policy expenses_update on public.expenses for update using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company())) with check(company_id=public.current_company_id());
create policy expenses_delete on public.expenses for delete using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.current_role()='admin'));
create policy revisions_read on public.expense_revisions for select using(exists(select 1 from public.expenses e where e.id=expense_id and e.company_id=public.current_company_id() and (e.employee_id=auth.uid() or public.can_manage_company())));
create policy revisions_insert on public.expense_revisions for insert with check(changed_by=auth.uid());
create policy shifts_read on public.attendance_shifts for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company()));
create policy shifts_insert on public.attendance_shifts for insert with check(company_id=public.current_company_id() and employee_id=auth.uid());
create policy shifts_update on public.attendance_shifts for update using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company())) with check(company_id=public.current_company_id());
create policy locations_read on public.attendance_locations for select using(exists(select 1 from public.attendance_shifts s where s.id=shift_id and s.company_id=public.current_company_id() and (s.employee_id=auth.uid() or public.can_manage_company())));
create policy locations_insert on public.attendance_locations for insert with check(exists(select 1 from public.attendance_shifts s where s.id=shift_id and s.employee_id=auth.uid() and s.company_id=public.current_company_id()));
create policy leave_balances_read on public.leave_balances for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company()));
create policy leave_balances_manage on public.leave_balances for all using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id() and public.can_manage_company());
create policy leave_requests_read on public.leave_requests for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company()));
create policy leave_requests_insert on public.leave_requests for insert with check(company_id=public.current_company_id() and employee_id=auth.uid());
create policy leave_requests_review on public.leave_requests for update using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id());
create policy assets_read on public.employee_assets for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.can_manage_company()));
create policy assets_manage on public.employee_assets for all using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id() and public.can_manage_company());
create policy salaries_read on public.salary_records for select using(company_id=public.current_company_id() and (employee_id=auth.uid() or public.current_role()='admin'));
create policy salaries_manage on public.salary_records for all using(company_id=public.current_company_id() and public.current_role()='admin') with check(company_id=public.current_company_id() and public.current_role()='admin');
create policy samples_read on public.client_samples for select using(company_id=public.current_company_id() and public.can_manage_company());
create policy samples_manage on public.client_samples for all using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id() and public.can_manage_company());
create policy orders_read on public.orders for select using(company_id=public.current_company_id() and (created_by=auth.uid() or assigned_to=auth.uid() or public.can_manage_company()));
create policy orders_manage on public.orders for all using(company_id=public.current_company_id() and public.can_manage_company()) with check(company_id=public.current_company_id() and public.can_manage_company());
create policy audit_read on public.audit_events for select using(company_id=public.current_company_id() and public.current_role()='admin');
create policy audit_insert on public.audit_events for insert with check(company_id=public.current_company_id() and actor_id=auth.uid());
create index expenses_company_date_idx on public.expenses(company_id,expense_date desc);
create index attendance_company_date_idx on public.attendance_shifts(company_id,shift_date desc);
create index orders_company_status_idx on public.orders(company_id,status,order_date desc);
create index leave_company_status_idx on public.leave_requests(company_id,status,start_date);
-- Never expose service_role keys in browser code. Configure storage policies separately.
